package io.baozhu.atlas.api; import io.baozhu.atlas.service.LineageService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/pipelines") public class LineageController {private final LineageService service;public LineageController(LineageService s){service=s;} @GetMapping("/{id}/lineage") public LineageResponse lineage(@PathVariable Long id){return service.get(id);}}
